fun launchPerformance() {

    val text = "Lorem ipsum dolor sit amet, consectetur adipiscing elit".repeat(10)
    "banana".repeat(5000)
    val patterns = listOf(
        "Lorem", "ipsum", "dolor", "sit", "amet",
        "consectetur", "adipiscing", "elit", "xyz", "abc"
    )

    measureTime("Rabin - Karp Algorithm") {
        rabinKarpMultiPattern(text, patterns)
    }

    measureTime("Sliding Window Algorithm") {
        slidingWindowClassic(text, patterns)
    }


}

private fun measureTime(message: String, block: () -> Unit) {
    val start = System.currentTimeMillis()
    block()
    val end = System.currentTimeMillis()
    println("$message Time - ${end - start} ms")
}


